export var AFWIJKINGEN_GRENS = [{"id":"nlbe-grens-gm1979","soort":"grensgemeente","tekst":"Eemsdelta (GM1979): 8850 m buitengrens binnen de zoekafstand van Duitsland, niet opgenomen. Claude 25-11-2026: de buitengrens van Eemsdelta bij Duitsland ligt alleen in het water van de Eems; daar hebben Nederland en Duitsland de grens niet vastgelegd (Eems-Dollardverdrag 1960). Geen landgrens, dus geen grensgemeente; een onzeker gegeven komt niet in een vraag (T1 par. 1.3). Open punt"}];
